/** 모든 컴포넌트의 Component CSS 변수 */
export type DsComponentVar = DsComponentVars[keyof DsComponentVars];

/** 제품 코드에서 쓸 수 있는 모든 CSS 변수 이름 */
export type DsCssVar = DsSemanticVar | DsComponentVar;

/** var() 참조 문자열. 예: style={{ color: v }} 에서 v의 타입 */
export type DsVarRef = `var(${DsCssVar})`;
